    showCrashDialog();
  }
});

onRecoverableError.example:
hydrateRoot(root, <App />, {
  onRecoverableError: (error, errorInfo) => {
    console.warn('Recoverable error:', error.message);
    analytics.track('recoverable_error', { cause: error.cause?.message });
  }
});

implementation.action:
'use server'
async function handleSubmit(prevState: FormState, formData: FormData) {
  const validated = schema.safeParse(Object.fromEntries(formData));
  if (!validated.success) return { errors: validated.error.flatten().fieldErrors };
  await db.create('items', validated.data);
  revalidatePath('/items');
  return { success: true };
}

